import{_ as i,o as n,c as t,a2 as u}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Teknolojia ya Mawasiliano kati ya Viwango","description":"","frontmatter":{},"headers":[],"relativePath":"sw/66-跨位面通讯技术.md","filePath":"sw/66-跨位面通讯技术.md"}'),o={name:"sw/66-跨位面通讯技术.md"};function w(s,a,k,m,e,h){return n(),t("div",null,[...a[0]||(a[0]=[u('<h1 id="teknolojia-ya-mawasiliano-kati-ya-viwango" tabindex="-1">Teknolojia ya Mawasiliano kati ya Viwango <a class="header-anchor" href="#teknolojia-ya-mawasiliano-kati-ya-viwango" aria-label="Permalink to &quot;Teknolojia ya Mawasiliano kati ya Viwango&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>66</td></tr><tr><td>Moduli</td><td>Mfumo wa Teknolojia na Nishati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Mawasiliano kati ya viwango, kunywa nafasi, mtandao wa nanga, usambazaji wa taarifa, usimbaji wa sheria</td></tr></tbody></table><h2 id="_1-changamoto-za-teknolojia-za-mawasiliano-kati-ya-viwango" tabindex="-1">1. Changamoto za Teknolojia za Mawasiliano kati ya Viwango <a class="header-anchor" href="#_1-changamoto-za-teknolojia-za-mawasiliano-kati-ya-viwango" aria-label="Permalink to &quot;1. Changamoto za Teknolojia za Mawasiliano kati ya Viwango&quot;">​</a></h2><p>Katika kiwango kimoja cha jadi, teknolojia ya mawasiliano inatumia mawimbi ya sumakuumeme kama njia kuu, kasi yake ya usambazaji imefadhiwa na kasi ya mwanga, na umbali wa usambazaji umefadhiwa na upungufu wa ishara. Kwa upande mwingine, katika muundo wa viwango vingi vya Hengyuanzhou, hakuna muunganisho wa moja kwa moja wa nafasi ya kimwili kati ya viwango, mawimbi ya sumakuumeme hayawezi kuvuka kizuizi kati ya viwango, na teknolojia ya mawasiliano ya jadi inashindwa kabisa.</p><p>Teknolojia ya mawasiliano kati ya viwango ni hasa teknolojia ya kiwango cha uhandisi wa sheria iliyoendelezwa kutatua tatizo hili. Inategemea mfumo wa kupanga sheria za nafasi na mtandao wa nanga, na inajenga njia za utumizi wa taarifa za kudumu kati ya viwango tofauti kupitia usimbaji wa sheria na kunywa nafasi. Teknolojia hii ni miundombinu ya msingi ya ustaarabu wa ushirika kufikia &quot;maendeleo pamoja ya kila rangi&quot; — bila mawasiliano kati ya viwango, maisha yaliyotawanyika katika viwango vingi vya hesabu hayawezi kujenga mtandao wa ushirika uliounganishwa.</p><h2 id="_2-kanuni-ya-msingi-ya-mawasiliano-kati-ya-viwango" tabindex="-1">2. Kanuni ya Msingi ya Mawasiliano kati ya Viwango <a class="header-anchor" href="#_2-kanuni-ya-msingi-ya-mawasiliano-kati-ya-viwango" aria-label="Permalink to &quot;2. Kanuni ya Msingi ya Mawasiliano kati ya Viwango&quot;">​</a></h2><p>Kanuni kuu ya mawasiliano kati ya viwango inaweza kufupishwa kama mchakato wa hatua nne: &quot;usimbaji wa sheria — handaki ya nafasi — usambazaji wa nanga — usimbaji wa sheria&quot;:</p><table tabindex="0"><thead><tr><th>Hatua</th><th>Jina</th><th>Maelezo ya Teknolojia</th><th>Vigezo vya Msingi</th></tr></thead><tbody><tr><td>Hatua ya kwanza</td><td>Usimbaji wa sheria</td><td>Kuandika taarifa zinazotakiwa kusambazwa katika mwigizaji wa sheria wa masafa fulani, si mawimbi ya sumakuumeme</td><td>Ufanisi wa usimbaji wa takriban 10^12 bit/mzunguko wa sheria</td></tr><tr><td>Hatua ya pili</td><td>Handaki ya nafasi</td><td>Kutumia teknolojia ya sheria ya nafasi kufungua njia za nafasi za ndogo za muda kwenye kizuizi kati ya viwango, mwigizaji wa sheria unapitia njia hadi kwenye kiwango cha lengwa kupitia njia</td><td>Kipekee cha njia cha takriban 10^-15 mita, muda mfupi sana</td></tr><tr><td>Hatua ya tatu</td><td>Usambazaji wa nanga</td><td>Mwigizaji wa sheria kupitia kukuza usambazaji na kupitia mtandao wa nanga, kuhakikisha utiilivu wa usambazaji wa umbali mrefu</td><td>Kucheleweshwa kwa usambazaji wa takriban 0,001 sekunde/rukio</td></tr><tr><td>Hatua ya nne</td><td>Usimbaji wa sheria</td><td>Mwisho wa kupokea unarejesha mwigizaji wa sheria kuwa taarifa asili, anakagua ukamilifu kabla ya kutoa kwa mtumiaji</td><td>Kiwango cha makosa ya usimbaji chini ya 10^-12</td></tr></tbody></table><p>Tofauti na mawasiliano ya jadi, njia ya taarifa ya mawasiliano kati ya viwango ni mwigizaji wa sheria, si mawimbi ya sumakuumeme. Mwigizaji wa sheria haufadhiwi na kasi ya mwanga, unaweza kutekeleza usambazaji wa karibu na wakati halisi kati ya viwango, na kucheleweshwa kwake kwa kina kinatokana hasa na muda wa usindikaji wa usambazaji wa nanga.</p><h2 id="_3-usanifu-wa-mtandao-wa-mawasiliano-kati-ya-viwango" tabindex="-1">3. Usanifu wa Mtandao wa Mawasiliano kati ya Viwango <a class="header-anchor" href="#_3-usanifu-wa-mtandao-wa-mawasiliano-kati-ya-viwango" aria-label="Permalink to &quot;3. Usanifu wa Mtandao wa Mawasiliano kati ya Viwango&quot;">​</a></h2><p>Mtandao wa mawasiliano kati ya viwango unachukua usanifu wa viwango vitatu: &quot;msingi wa nanga — ufikiaji wa kiwango — kifaa cha mwisho&quot;:</p><ol><li><strong>Mtandao wa msingi wa nanga</strong>: Unaunganishwa na nanga kuu zilizowekwa kwenye viwango vikuu, ni msingi wa msingi wa mawasiliano kati ya viwango. Nanga kuu zinaunganishwa kwa njia za sheria zenye upana wa bandari juu, upana wa bandari wa njia moja unaweza kufika 10^15 bit/s. Mtandao wa msingi unachukua muundo wa ziada za njia nyingi, kushindwa kwa njia moja hakuna athari kwa uunganishaji wa jumla</li><li><strong>Mtandao wa ufikiaji wa kiwango</strong>: Ndani ya kila kiwango, nanga za pili na vituo vya msingi vya sheria ya nafasi vinajenga mtandao wa ufikiaji wa kiwango hicho. Mtandao wa ufikiaji unawajibika kuunganisha ishara za vifaa vya mwisho kwenye mtandao wa msingi wa nanga, wakati huo huo unagawanya taarifa za mtandao wa msingi kwa vifaa vya mwisho</li><li><strong>Kifaa cha mwisho</strong>: Vifaa vya mwisho vya mawasiliano kati ya viwango vinavyotumika na wanaofanya mazoezi na taasisi, ikiwa ni pamoja na mawasilisho wa kibinafsi, kituo cha mawasiliano cha kudumu, moduli ya mawasiliano iliyoingizwa, n.k. Vifaa vya mwisho vina usimbaji-wasimbaji wa sheria wa ndogo ulioingizwa, vinaweza kuwasiliana moja kwa moja na mtandao wa ufikiaji</li></ol><p>Algoritmu ya kupitia njia ya mtandao wa mawasiliano inategemea mfumo wa majibu ya ushirika wa mtandao wa nanga, inaweza kuhisi wakati halisi mzigo na utiilivu wa kila njia, na kwa nguvu kuchagua njia bora ya usambazaji.</p><h2 id="_4-viwango-vya-mawasiliano-na-aina-za-huduma" tabindex="-1">4. Viwango vya Mawasiliano na Aina za Huduma <a class="header-anchor" href="#_4-viwango-vya-mawasiliano-na-aina-za-huduma" aria-label="Permalink to &quot;4. Viwango vya Mawasiliano na Aina za Huduma&quot;">​</a></h2><p>Mawasiliano kati ya viwango yanagawanywa katika viwango vingi vya huduma kulingana na upana wa bandari na kipaumbele:</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Upana wa Bandari</th><th>Matumizi ya Kawaida</th><th>Kipaumbele</th></tr></thead><tbody><tr><td>Kiwango cha Maalum</td><td>Njia maalum ya nanga</td><td>≥10^15 bit/s</td><td>Usawazishaji wa nanga, operesheni za kuinua mwelekeo</td><td>Juu zaidi</td></tr><tr><td>Kiwango cha 1</td><td>Mawasiliano ya kiwango cha ustaarabu</td><td>10^12—10^15 bit/s</td><td>Mawasiliano ya serikali kati ya viwango, tangazo la dharura</td><td>Juu</td></tr><tr><td>Kiwango cha 2</td><td>Mawasiliano ya kiwango cha taasisi</td><td>10^9—10^12 bit/s</td><td>Taasisi za utafiti, makampuni makubwa, mtandao wa elimu</td><td>Wastani</td></tr><tr><td>Kiwango cha 3</td><td>Mawasiliano ya kibiashara</td><td>10^6—10^9 bit/s</td><td>Mawasiliano ya kibiashara, usambazaji wa vyombo vya habari</td><td>Kawaida</td></tr><tr><td>Kiwango cha 4</td><td>Mawasiliano ya kiraia</td><td>≤10^6 bit/s</td><td>Mawasiliano ya kibinafsi, taarifa za kila siku</td><td>Msingi</td></tr></tbody></table><p>Viwango vyote vya huduma za mawasiliano vinafuata kanuni ya &quot;msingi bure, thamani ya ziada inalipwa&quot;. Huduma za mawasiliano za msingi za kiwango cha kiraia zinapatikana bure na ustaarabu wa ushirika, kuhakikisha utekelezaji wa &quot;kila mtu ana njia&quot; katika uwanja wa mawasiliano; huduma za thamani ya ziada zenye upana wa bandari juu na kipaumbele juu zinachukua gharama nzuri kulingana na matumizi ya nisha.</p><h2 id="_5-usalama-wa-mawasiliano-na-maadili" tabindex="-1">5. Usalama wa Mawasiliano na Maadili <a class="header-anchor" href="#_5-usalama-wa-mawasiliano-na-maadili" aria-label="Permalink to &quot;5. Usalama wa Mawasiliano na Maadili&quot;">​</a></h2><p>Usalama na maadili ya mawasiliano kati ya viwango yamefadhiwa kwa mkali:</p><ul><li><strong>Kiwangoo cha usimbaji</strong>: Mawasiliano yote kati ya viwango yanapaswa kuchukua usimbaji wa mwisho-kwa-mwisho wa kiwango cha nanga, ufunguo wa usimbaji unatengenezwa na kizazi cha nambari za kweli za nasibu cha mtandao wa nanga, kwa nadharia haiwezi kuvunjwa</li><li><strong>Ulinzi wa faragha</strong>: Maudhui ya mawasiliano yanalindwa mara mbili na Katiba ya Ushirika na sheria ya ulinzi wa watumiaji, hakuna taasisi au mtu anaweza kusikia au kuzuia taarifa za mawasiliano bila idhini</li><li><strong>Kuzuia na kudhibiti uchafuzi wa taarifa</strong>: Mtandao wa mawasiliano una vifaa vya kuchuja taarifa vya kiwango cha sheria, kuzuia taarifa hatari kama vile mbinu za mazoezi ya mawingu, mifumo ya fahamu yenye madhara kuenea kupitia mtandao wa mawasiliano</li><li><strong>Mamlaka ya tangazo la dharura</strong>: Katika hali ya dharura ya kiwango cha ustaarabu, taasisi ya utawala wa ushirika ina mamlaka ya kutangaza dharura kwa viwango vyote kupitia njia maalum, mamlaka hii iko chini ya ufuatiliaji wa kisheria mkali</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Teknolojia ya mawasiliano kati ya viwango ni &quot;mfumo wa neva&quot; wa ustaarabu wa ushirika wa nanga. Inaunganisha maisha yaliyotawanyika katika viwango vingi vya hesabu kuwa jumuiya ya taarifa iliyounganishwa, na kufanya majibu na usawazishaji wa mtandao wa ushirika kuwa yawezekana. Pamoja na kuongezeka kwa kuendelea kwa upana wa bandari wa mawasiliano na kupungua kwa kuendelea kwa kucheleweshwa, Hengyuanzhou inabadilika kwa mwelekeo wa &quot;kujumuika pamoja kwa wakati halisi wa kila rangi&quot;, ambayo imeweka msingi wa mawasiliano kwa ushirika wa fahamo ya pamoja katika hatua ya mageuzi ya fahamu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>62-Utekelezaji wa Teknolojia ya Sheria ya Nafasi</li><li>67-Vifaa vya Nanga na Miundombinu</li><li>21-Kanuni ya Uendeshaji wa Mtandao wa Ushirika</li></ul>',24)])])}const r=i(o,[["render",w]]);export{l as __pageData,r as default};
